package de.terrestris.shoguncore.hibernate;

import jakarta.persistence.AttributeConverter;
import jakarta.persistence.Converter;
import org.joda.time.DateTime;
import org.joda.time.ReadableDateTime;

import java.sql.Timestamp;

/**
 * JPA converter that stores Joda-Time date/times (as {@link ReadableDateTime})
 * in a timestamp column. Values are read back in the default time zone of the
 * JVM, which matches the behaviour of the Jadira user type that was used before
 * the migration to Hibernate 6.
 */
@Converter
public class JodaDateTimeConverter implements AttributeConverter<ReadableDateTime, Timestamp> {

    @Override
    public Timestamp convertToDatabaseColumn(ReadableDateTime attribute) {
        if (attribute == null) {
            return null;
        }
        return new Timestamp(attribute.getMillis());
    }

    @Override
    public ReadableDateTime convertToEntityAttribute(Timestamp dbData) {
        if (dbData == null) {
            return null;
        }
        return new DateTime(dbData.getTime());
    }

}
