package de.terrestris.shoguncore.hibernate;

import jakarta.persistence.AttributeConverter;
import jakarta.persistence.Converter;
import org.joda.time.LocalDate;

import java.sql.Date;

/**
 * JPA converter that stores Joda-Time {@link LocalDate}s in a date column, using
 * the default time zone of the JVM.
 */
@Converter
public class JodaLocalDateConverter implements AttributeConverter<LocalDate, Date> {

    @Override
    public Date convertToDatabaseColumn(LocalDate attribute) {
        if (attribute == null) {
            return null;
        }
        return new Date(attribute.toDateTimeAtStartOfDay().getMillis());
    }

    @Override
    public LocalDate convertToEntityAttribute(Date dbData) {
        if (dbData == null) {
            return null;
        }
        return new LocalDate(dbData.getTime());
    }

}
