    extends GenericHibernateDao<E, Integer> {
    /**
     * Public default constructor for this DAO.
     */
    @SuppressWarnings("unchecked")
    public InterceptorRuleDao() {
        super((Class<E>) InterceptorRule.class);
    }
    /**
