package de.terrestris.shoguncore.dao;

import java.util.Objects;

/** A sort order of a DAO query: a property name and a direction. */
public final class SortOrder {

    private final String property;

    private final boolean ascending;

    private SortOrder(String property, boolean ascending) {
        this.property = Objects.requireNonNull(property, "property must not be null");
        this.ascending = ascending;
    }

    /**
     * @param property the name of the property to sort by (ascending)
     * @return the ascending sort order for the property
     */
    public static SortOrder asc(String property) {
        return new SortOrder(property, true);
    }

    /**
     * @param property the name of the property to sort by (descending)
     * @return the descending sort order for the property
     */
    public static SortOrder desc(String property) {
        return new SortOrder(property, false);
    }

    /** @return the name of the property to sort by */
    public String getProperty() {
        return property;
    }

    /** @return true if the sort direction is ascending */
    public boolean isAscending() {
        return ascending;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof SortOrder)) {
            return false;
        }
        SortOrder other = (SortOrder) o;
        return ascending == other.ascending && property.equals(other.property);
    }

    @Override
    public int hashCode() {
        return Objects.hash(property, ascending);
    }

    @Override
    public String toString() {
        return property + (ascending ? " asc" : " desc");
    }
}
