/**
 * The superclass for all data access objects. Provides basic CRUD
 * functionality and a logger instance for all subclasses.
 *
 * @author Nils Bühner
 */
@Repository("genericDao")
public class GenericHibernateDao<E extends PersistentObject, ID extends Serializable> {

    /**
     * The LOGGER instance (that will be available in all subclasses)
     */
    protected static final Logger logger = getLogger(GenericHibernateDao.class);

    /**
     * Represents the class of the entity
     */
    private final Class<E> entityClass;

    @Value("${hibernate.cache.use_query_cache}")
    private Boolean useQueryCache;
    /**
     * Hibernate SessionFactory
     */
    @Autowired
    private SessionFactory sessionFactory;

    /**
     * Default constructor
     */
    @SuppressWarnings("unchecked")
    public GenericHibernateDao() {
        this((Class<E>) PersistentObject.class);
    }

    /**
     * Constructor
     *
     * @param clazz
     */
    protected GenericHibernateDao(Class<E> clazz) {
        this.entityClass = clazz;
    }

    /**
     * Obtains the current session.
     *
     * @return
     */
    private Session getSession() {
        return sessionFactory.getCurrentSession();
    }

    /**
     * Return the real object from the database. Returns null if the object does
     * not exist.
     *
     * @param id
     * @return The object from the database or null if it does not exist
     * @see http://www.mkyong.com/hibernate/different-between-session-get-and-session-load/
     */
    public E findById(ID id) {
        logger.trace("Finding " + entityClass.getSimpleName() + " with ID " + id);
        return getSession().get(entityClass, id);
    }

    /**
     * Returns a list of entity objects that have field named
     * <code>fieldName</code>, which has an object <code>fieldEntity</code>
     * as value.
     *
     * @param fieldName    The name of the field
     * @param fieldEntity  The element that should be set as value
     * @param restrictions Additional restrictions to apply (optional)
     * @return The list of objects
     */
    public List<E> findAllWhereFieldEquals(String fieldName, Object fieldEntity,
                                           QueryRestriction<E>... restrictions) {

        Class<?> fieldEntityType = null;

        if (fieldEntity != null) {
            fieldEntityType = fieldEntity.getClass();
        }

        final boolean isField = EntityUtil.isField(entityClass, fieldName, fieldEntityType, true);

        if (!isField) {
            String errorMsg = String.format(
                "There is no field '%s' in the type '%s' that accepts instances of '%s'",
                fieldName,
                entityClass.getName(),
                fieldEntityType.getName()
            );
            throw new IllegalArgumentException(errorMsg);
        }

        QueryRestriction<E> fieldRestriction = (root, query, cb) -> {
            Path<Object> path = root.get(fieldName);
            if (fieldEntity == null) {
                return cb.isNull(path);
            }
            return cb.equal(path, fieldEntity);
        };

        return queryEntities(toList(restrictions, fieldRestriction), null, null, null);
    }

    /**
     * Returns a list of entity objects that have a collection named
     * <code>fieldName</code>, which contains the passed
     * <code>subElement</code>.
     * <p>
     * The can e.g. be used to return all applications that contain a certain layer.
     *
     * @param fieldName    The name of the collection field
     * @param subElement   The element that should be contained in the collection
     * @param restrictions Additional restrictions to apply (optional)
     * @return The list of objects
     */
    public List<E> findAllWithCollectionContaining(String fieldName, PersistentObject subElement,
                                                   QueryRestriction<E>... restrictions) {
        final Class<? extends PersistentObject> subElementType = subElement.getClass();

        final boolean isCollectionField = EntityUtil.isCollectionField(entityClass, fieldName, subElementType, true);

        if (!isCollectionField) {
            String errorMsg = String.format(
                "There is no collection field '%s' with element type '%s' in the type '%s'",
                fieldName,
                subElementType.getName(),
                entityClass.getName()
            );
            throw new IllegalArgumentException(errorMsg);
        }

        QueryRestriction<E> collectionRestriction = (root, query, cb) -> {
            Join<E, Object> sub = root.join(fieldName);
            return cb.equal(sub.get("id"), subElement.getId());
        };

        return queryEntities(toList(restrictions, collectionRestriction), null, null, null);
    }

    /**
     * Return a proxy of the object (without hitting the database). This should
     * only be used if it is assumed that the object really exists and where
     * non-existence would be an actual error.
     *
     * @param id
     * @return
     * @see http://www.mkyong.com/hibernate/different-between-session-get-and-session-load/
     */
    public E loadById(ID id) {
        logger.trace("Loading " + entityClass.getSimpleName() + " with ID " + id);
        return getSession().load(entityClass, id);
    }

    /**
     * Returns all Entities by calling findByCriteria(), i.e. without arguments.
     *
     * @return All entities
     * @see GenericHibernateDao#findByCriteria(QueryRestriction...)
     */
    public List<E> findAll() throws HibernateException {
        logger.trace("Finding all instances of " + entityClass.getSimpleName());
        return findByCriteria();
    }

    /**
     * Saves or updates the passed entity.
     *
     * @param e The entity to save or update in the database.
     */
    public void saveOrUpdate(E e) {
        final Integer id = e.getId();
        final boolean hasId = id != null;
        String createOrUpdatePrefix = hasId ? "Updating" : "Creating a new";
        String idSuffix = hasId ? " with ID " + id : "";

        logger.trace(createOrUpdatePrefix + " instance of " + entityClass.getSimpleName()
            + idSuffix);

        e.setModified(DateTime.now());
        getSession().saveOrUpdate(e);
    }

    /**
     * Deletes the passed entity.
     *
     * @param e The entity to remove from the database.
     */
    public void delete(E e) {
        logger.trace("Deleting " + entityClass.getSimpleName() + " with ID " + e.getId());
        getSession().delete(e);
    }

    /**
     * Unproxy the entity (and eagerly fetch properties).
     */
    @SuppressWarnings("unchecked")
    public E unproxy(E e) {
        if (e == null) {
            throw new NullPointerException("Entity passed for initialization is null");
        }

        Hibernate.initialize(e);

        if (e instanceof HibernateProxy) {
            e = (E) ((HibernateProxy) e).getHibernateLazyInitializer().getImplementation();
        }

        return e;
    }

    /**
     * Detach an entity from the hibernate session
     *
     * @param e
     */
    public void evict(E e) {
        logger.trace("Detaching " + entityClass.getSimpleName() + " with ID " + e.getId() + " from hibernate session");
        getSession().evict(e);
    }

    /**
     * Gets the results, that match a variable number of passed restrictions. Call
     * this method without arguments to find all entities.
     *
     * @param restrictions A variable number of restrictions, combined with AND
     * @return Entities matching the passed restrictions
     */
    public List<E> findByCriteria(QueryRestriction<E>... restrictions) throws HibernateException {
        logger.trace("Finding instances of " + entityClass.getSimpleName()
            + " based on " + restrictionCount(restrictions) + " criteria");

        return queryEntities(toList(restrictions), null, null, null);
    }

    /**
     * Gets the results, that match a variable number of passed restrictions, but return a
     * stripped version of the entities, where only the fieldNames in <code>restrictFieldNames</code>
     * have their actual values set.
     * <p>
     * You can call this with <code>restrictFieldNames</code> = <code>null</code> to get the full
     * entities back.
     * <p>
     * You can call this method without restriction arguments to find all entities (stripped down to
     * the <code>restrictFieldNames</code>).
     * <p>
     * If this is called as <code>findByCriteriaRestricted(null)</code> the return value equals the
     * return value of <code>findByCriteria()</code>.
     *
     * @param restrictFieldNames
     * @param restrictions
     * @return
     * @throws HibernateException
     */
    public List<E> findByCriteriaRestricted(List<String> restrictFieldNames, QueryRestriction<E>... restrictions) throws HibernateException {
        logger.trace("Finding instances of " + entityClass.getSimpleName()
            + " based on " + restrictionCount(restrictions) + " criteria");

        if (restrictFieldNames == null) {
            return queryEntities(toList(restrictions), null, null, null);
        }

        CriteriaBuilder cb = getSession().getCriteriaBuilder();
        CriteriaQuery<Tuple> query = cb.createTupleQuery();
        Root<E> root = query.from(entityClass);

        List<Selection<?>> selections = new ArrayList<>();
        for (String restrictFieldName : restrictFieldNames) {
            selections.add(resolvePath(root, restrictFieldName).alias(restrictFieldName));
        }
        query.multiselect(selections);
        applyPredicates(root, query, cb, toList(restrictions));

        Query<Tuple> typedQuery = getSession().createQuery(query);
        typedQuery.setHint(HibernateHints.HINT_CACHEABLE, isQueryCacheEnabled());

        List<E> results = new ArrayList<>();
        for (Tuple tuple : typedQuery.getResultList()) {
            E instance = BeanUtils.instantiateClass(entityClass);
            BeanWrapper wrapper = PropertyAccessorFactory.forBeanPropertyAccess(instance);
            for (String restrictFieldName : restrictFieldNames) {
                wrapper.setPropertyValue(restrictFieldName, tuple.get(restrictFieldName));
            }
            results.add(instance);
        }
        return results;
    }

    /**
     * Gets the unique result, that matches a variable number of passed
     * restrictions.
     *
     * @param restrictions A variable number of restrictions, combined with AND
     * @return Entity matching the passed restrictions or null if there is none
     * @throws HibernateException if there is more than one matching result
     */
    public E findByUniqueCriteria(QueryRestriction<E>... restrictions) throws HibernateException {
        logger.trace("Finding one unique " + entityClass.getSimpleName()
            + " based on " + restrictionCount(restrictions) + " criteria");

        // fetch at most two rows to be able to detect non-unique results
        List<E> results = queryEntities(toList(restrictions), null, null, 2);
        if (results.isEmpty()) {
            return null;
        }
        if (results.size() > 1) {
            throw new NonUniqueResultException(results.size());
        }
        return results.get(0);
    }

    /**
     * Gets the results, that match a variable number of passed restrictions,
     * considering the paging- and sort-info at the same time.
     *
     * @param firstResult Starting index for the paging request.
     * @param maxResults  Max number of result size.
     * @param sorters     The sort orders to apply (optional)
     * @param restrictions A variable number of restrictions, combined with AND
     * @return
     */
    public PagingResult<E> findByCriteriaWithSortingAndPaging(Integer firstResult,
                                                              Integer maxResults, List<SortOrder> sorters, QueryRestriction<E>... restrictions) throws HibernateException {

        int nrOfSorters = sorters == null ? 0 : sorters.size();

        logger.trace("Finding instances of " + entityClass.getSimpleName()
            + " based on " + restrictionCount(restrictions) + " criteria"
            + " with " + nrOfSorters + " sorters");

        if (maxResults != null) {
            logger.trace("Limiting result set size to " + maxResults);
        }
        if (firstResult != null) {
            logger.trace("Setting the first result to be retrieved to "
                + firstResult);
        }

        List<E> results = queryEntities(toList(restrictions), sorters, firstResult, maxResults);

        return new PagingResult<E>(results, getTotalCount(restrictions));
    }

    /**
     * This method returns a {@link Map} that maps {@link PersistentObject}s
     * to PermissionCollections for the passed {@link User}. I.e. the keySet
     * of the map is the collection of all {@link PersistentObject}s where the
     * user has at least one permission and the corresponding value contains
     * the {@link PermissionCollection} for the passed user on the entity.
     *
     * @param user
     * @return
     */
    public Map<PersistentObject, PermissionCollection> findAllUserPermissionsOfUser(User user) {

        // by only joining the association, we will only get those entities where
        // there is at least one permission set...
        // it is hard (or even impossible in this scenario) to create a
        // restriction that filters for permissions of the given user only.
        // using HQL here is no option as the PersistentObject is
        // a MappedSuperclass (without table).
        // another efficient way would be a SQL query, but then the SQL
        // would be written in an explicit SQL dialect...
        List<PersistentObject> entitiesWithPermissions = findEntitiesWithPermissions("userPermissions");

        Map<PersistentObject, PermissionCollection> userPermissions = new HashMap<PersistentObject, PermissionCollection>();

        // TODO find a better way than iterating over all entities of the system
        // that have at least one permission (for any user) (see comment above)
        for (PersistentObject entity : entitiesWithPermissions) {
            Map<User, PermissionCollection> entityUserPermissions = entity.getUserPermissions();
            if (entityUserPermissions.containsKey(user)) {
                userPermissions.put(entity, entityUserPermissions.get(user));
            }
        }

        return userPermissions;
    }

    /**
     * This method returns a {@link Map} that maps {@link PersistentObject}s
     * to PermissionCollections for the passed {@link UserGroup}. I.e. the keySet
     * of the map is the collection of all {@link PersistentObject}s where the
     * user group has at least one permission and the corresponding value contains
     * the {@link PermissionCollection} for the passed user group on the entity.
     *
     * @param userGroup
     * @return
     */
    public Map<PersistentObject, PermissionCollection> findAllUserGroupPermissionsOfUserGroup(UserGroup userGroup) {

        // see findAllUserPermissionsOfUser for the reasoning behind this approach
        List<PersistentObject> entitiesWithPermissions = findEntitiesWithPermissions("groupPermissions");

        Map<PersistentObject, PermissionCollection> userGroupPermissions = new HashMap<PersistentObject, PermissionCollection>();

        // TODO find a better way than iterating over all entities of the system
        // that have at least one permission (for any user) (see comment above)
        for (PersistentObject entity : entitiesWithPermissions) {
            Map<UserGroup, PermissionCollection> entityUserGroupPermissions = entity.getGroupPermissions();
            if (entityUserGroupPermissions.containsKey(userGroup)) {
                userGroupPermissions.put(entity, entityUserGroupPermissions.get(userGroup));
            }
        }

        return userGroupPermissions;
    }

    /**
     * Returns the total count of db entries for the current type that match
     * the passed restrictions (distinct entities).
     *
     * @param restrictions
     * @return
     */
    public Number getTotalCount(QueryRestriction<E>... restrictions) throws HibernateException {
        CriteriaBuilder cb = getSession().getCriteriaBuilder();
        CriteriaQuery<Long> query = cb.createQuery(Long.class);
        Root<E> root = query.from(entityClass);
        query.select(cb.countDistinct(root));
        applyPredicates(root, query, cb, toList(restrictions));

        Query<Long> typedQuery = getSession().createQuery(query);
        typedQuery.setHint(HibernateHints.HINT_CACHEABLE, isQueryCacheEnabled());
        return typedQuery.uniqueResult();
    }

    /**
     * @return the entityClass
     */
    public Class<E> getEntityClass() {
        return entityClass;
    }

    /**
     * Helper method: Runs a distinct query for the {@link #entityClass} of this
     * dao, with the given restrictions (ANDed), sort orders and paging.
     *
     * @param restrictions The restrictions (null entries are ignored)
     * @param sorters      The sort orders (optional)
     * @param firstResult  The first result to return (optional)
     * @param maxResults   The maximum number of results to return (optional)
     * @return the matching entities
     */
    private List<E> queryEntities(List<QueryRestriction<E>> restrictions, List<SortOrder> sorters,
                                  Integer firstResult, Integer maxResults) {
        CriteriaBuilder cb = getSession().getCriteriaBuilder();
        CriteriaQuery<E> query = cb.createQuery(entityClass);
        Root<E> root = query.from(entityClass);
        query.select(root).distinct(true);

        applyPredicates(root, query, cb, restrictions);
        applyOrders(root, query, cb, sorters);

        Query<E> typedQuery = getSession().createQuery(query);
        typedQuery.setHint(HibernateHints.HINT_CACHEABLE, isQueryCacheEnabled());
        if (firstResult != null) {
            typedQuery.setFirstResult(firstResult);
        }
        if (maxResults != null) {
            typedQuery.setMaxResults(maxResults);
        }
        return typedQuery.getResultList();
    }

    /**
     * Adds the predicates of all non-null restrictions to the query (ANDed).
     */
    private void applyPredicates(Root<E> root, CriteriaQuery<?> query, CriteriaBuilder cb,
                                 List<QueryRestriction<E>> restrictions) {
        List<Predicate> predicates = new ArrayList<>();
        for (QueryRestriction<E> restriction : restrictions) {
            if (restriction != null) {
                Predicate predicate = restriction.toPredicate(root, query, cb);
                if (predicate != null) {
                    predicates.add(predicate);
                }
            }
        }
        if (!predicates.isEmpty()) {
            query.where(predicates.toArray(new Predicate[0]));
        }
    }

    /**
     * Adds the sort orders (in the given sequence) to the query.
     */
    private void applyOrders(Root<E> root, CriteriaQuery<?> query, CriteriaBuilder cb, List<SortOrder> sorters) {
        if (sorters == null || sorters.isEmpty()) {
            return;
        }
        List<jakarta.persistence.criteria.Order> orders = new ArrayList<>();
        for (SortOrder sorter : sorters) {
            Path<?> path = resolvePath(root, sorter.getProperty());
            orders.add(sorter.isAscending() ? cb.asc(path) : cb.desc(path));
        }
        query.orderBy(orders);
    }

    /**
     * Resolves a (possibly dotted, e.g. "user.id") property name to a path of
     * the given root.
     */
    private Path<?> resolvePath(Root<E> root, String property) {
        Path<?> path = root;
        for (String part : property.split("\\.")) {
            path = path.get(part);
        }
        return path;
    }

    /**
     * Returns all entities (of all entity types that extend
     * {@link PersistentObject}) that have at least one entry in the given
     * association (map).
     *
     * @param association the name of the map attribute, e.g. userPermissions
     */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private List<PersistentObject> findEntitiesWithPermissions(String association) {
        List<PersistentObject> result = new ArrayList<>();
        // PersistentObject is a MappedSuperclass, so the query is run for every
        // concrete entity type that extends it
        Set<Class<?>> entityTypes = new LinkedHashSet<>();
        for (EntityType<?> entityType : getSession().getMetamodel().getEntities()) {
            if (PersistentObject.class.isAssignableFrom(entityType.getJavaType())) {
                entityTypes.add(entityType.getJavaType());
            }
        }
        for (Class<?> entityType : entityTypes) {
            result.addAll(findEntitiesWithAssociation((Class) entityType, association));
        }
        return result;
    }

    private <T extends PersistentObject> List<T> findEntitiesWithAssociation(Class<T> type, String association) {
        CriteriaBuilder cb = getSession().getCriteriaBuilder();
        CriteriaQuery<T> query = cb.createQuery(type);
        Root<T> root = query.from(type);
        query.select(root).distinct(true);
        root.joinMap(association);
        return getSession().createQuery(query).getResultList();
    }

    /**
     * Helper method: Converts the (optional) restrictions array to a list.
     */
    @SafeVarargs
    private static <E> List<QueryRestriction<E>> toList(QueryRestriction<E>... restrictions) {
        List<QueryRestriction<E>> list = new ArrayList<>();
        if (restrictions != null) {
            for (QueryRestriction<E> restriction : restrictions) {
                list.add(restriction);
            }
        }
        return list;
    }

    /**
     * Helper method: Converts the (optional) restrictions array to a list and
     * appends the additional restriction.
     */
    @SafeVarargs
    private static <E> List<QueryRestriction<E>> toList(QueryRestriction<E>[] restrictions, QueryRestriction<E> additional) {
        List<QueryRestriction<E>> list = toList(restrictions);
        list.add(additional);
        return list;
    }

    private static int restrictionCount(Object[] restrictions) {
        return restrictions == null ? 0 : restrictions.length;
    }

    private boolean isQueryCacheEnabled() {
        return Boolean.TRUE.equals(this.useQueryCache);
    }

}
