mkdir -p /tmp/conv && cat > /tmp/conv/convert.py <<'PYEOF'
import re, sys, os

ASSERT_NAMES = ['assertTrue','assertFalse','assertNull','assertNotNull','assertSame','assertNotSame',
                'assertEquals','assertNotEquals','assertArrayEquals','fail']
TWO_ARG_MSG = {'assertTrue','assertFalse','assertNull','assertNotNull','assertSame','assertNotSame'}
THREE_ARG_MSG = {'assertEquals','assertNotEquals','assertArrayEquals'}

def split_args(s, start):
    """s[start] is just after '('. Return (list of (argtext), end_index_of_close_paren)."""
    depth = 0; i = start; args = []; cur = []; in_str = None
    while i < len(s):
        c = s[i]
        if in_str:
            cur.append(c)
            if c == '\\':
                cur.append(s[i+1]); i += 2; continue
            if c == in_str:
                in_str = None
            i += 1; continue
        if c in '"\'':
            in_str = c; cur.append(c); i += 1; continue
        if c in '([{':
            depth += 1
        elif c in ')]}':
            if depth == 0:
                args.append(''.join(cur).strip())
                return args, i
            depth -= 1
        elif c == ',' and depth == 0:
            args.append(''.join(cur).strip()); cur = []; i += 1; continue
        cur.append(c); i += 1
    raise ValueError('unbalanced')

def is_literal_msg(a):
    return a.startswith('"') or a.startswith("'") or a.startswith('String.format') or a.startswith('"')

def reorder_asserts(src, path, warnings):
    out = []; i = 0
    pat = re.compile(r'(?<![\w.])(?:Assertions\.|Assert\.)?(' + '|'.join(ASSERT_NAMES) + r')\s*\(')
    pos = 0
    res = []
    for m in pat.finditer(src):
        if m.start() < pos:
            continue
        name = m.group(1)
        # skip declarations / definitions (e.g. "void fail(") and comments are ignored best-effort
        line_start = src.rfind('\n', 0, m.start()) + 1
        line = src[line_start: src.find('\n', m.start())]
        if re.search(r'\bvoid\s+' + name, line) or line.lstrip().startswith('//') or line.lstrip().startswith('*'):
            continue
        open_idx = m.end()
        args, close = split_args(src, open_idx)
        new_args = None
        if name in TWO_ARG_MSG and len(args) == 2:
            new_args = [args[1], args[0]]
        elif name in THREE_ARG_MSG and len(args) == 3:
            if is_literal_msg(args[0]):
                new_args = [args[1], args[2], args[0]]
            else:
                warnings.append('%s: ambiguous 3-arg %s(%s)' % (path, name, ', '.join(args)[:150]))
        elif name == 'fail' and len(args) == 1:
            new_args = None
        if new_args is not None:
            prefix = src[m.start(): open_idx]
            res.append(src[pos:m.start()])
            res.append(prefix + ', '.join(new_args) + ')')
            pos = close + 1
    res.append(src[pos:])
    return ''.join(res)

def wrap_expected(src):
    pat = re.compile(r'@Test\(expected\s*=\s*([\w.]+)\.class\)\s*\n(\s*)(public |protected |private )?void (\w+)\(\)\s*(throws [\w., ]+)?\s*\{')
    while True:
        m = pat.search(src)
        if not m:
            break
        exc = m.group(1)
        body_open = m.end() - 1
        # find matching brace
        depth = 0; i = body_open; in_str = None
        while True:
            c = src[i]
            if in_str:
                if c == '\\': i += 2; continue
                if c == in_str: in_str = None
            elif c in '"\'':
                in_str = c
            elif c == '{': depth += 1
            elif c == '}':
                depth -= 1
                if depth == 0: break
            i += 1
        body = src[body_open+1:i]
        indent = m.group(2)
        new_body = '\n' + indent + '    assertThrows(' + exc + '.class, () -> {' + body.rstrip() + '\n' + indent + '    });\n' + indent
        new = '@Test\n' + indent + (m.group(3) or '') + 'void ' + m.group(4) + '() ' + (m.group(5) + ' ' if m.group(5) else '') + '{' + new_body + '}'
        src = src[:m.start()] + new + src[i+1:]
    return src

def convert(path, warnings):
    s = open(path, encoding='utf-8').read()
    orig = s
    s = s.replace('import org.junit.Test;', 'import org.junit.jupiter.api.Test;')
    s = s.replace('import org.junit.Before;', 'import org.junit.jupiter.api.BeforeEach;')
    s = s.replace('import org.junit.After;', 'import org.junit.jupiter.api.AfterEach;')
    s = s.replace('import org.junit.BeforeClass;', 'import org.junit.jupiter.api.BeforeAll;')
    s = s.replace('import org.junit.AfterClass;', 'import org.junit.jupiter.api.AfterAll;')
    s = re.sub(r'@Before\b', '@BeforeEach', s)
    s = re.sub(r'@After\b', '@AfterEach', s)
    s = re.sub(r'@BeforeClass\b', '@BeforeAll', s)
    s = re.sub(r'@AfterClass\b', '@AfterAll', s)
    s = s.replace('import static org.junit.Assert.*;', 'import static org.junit.jupiter.api.Assertions.*;')
    s = s.replace('import org.junit.Assert;', 'import org.junit.jupiter.api.Assertions;')
    s = re.sub(r'\bAssert\.(?=\w)', 'Assertions.', s)
    # static imports of individual members
    def fix_static(m):
        member = m.group(1)
        if member == 'assertThat':
            return 'import static org.hamcrest.MatcherAssert.assertThat;'
        return 'import static org.junit.jupiter.api.Assertions.%s;' % member
    s = re.sub(r'import static org\.junit\.Assert\.(\w+);', fix_static, s)
    s = s.replace('import org.junit.runner.RunWith;\n', '')
    if '@RunWith(SpringJUnit4ClassRunner.class)' in s:
        s = s.replace('@RunWith(SpringJUnit4ClassRunner.class)', '@ExtendWith(SpringExtension.class)')
        s = s.replace('import org.springframework.test.context.junit4.SpringJUnit4ClassRunner;',
                      'import org.springframework.test.context.junit.jupiter.SpringExtension;')
    if '@ExtendWith(' in s and 'import org.junit.jupiter.api.extension.ExtendWith;' not in s:
        s = re.sub(r'(\nimport )', r'\nimport org.junit.jupiter.api.extension.ExtendWith;\1', s, count=1)
    s = wrap_expected(s)
    s = reorder_asserts(s, path, warnings)
    if s != orig:
        open(path, 'w', encoding='utf-8').write(s)
    return s != orig

if __name__ == '__main__':
    warnings = []
    changed = 0
    for p in sys.argv[1:]:
        if convert(p, warnings):
            changed += 1
    print('changed', changed)
    for w in warnings:
        print('WARN', w)
