package de.terrestris.shoguncore.dao;

import de.terrestris.shoguncore.model.Application;
import de.terrestris.shoguncore.model.PersistentObject;
import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.interceptor.InterceptorRule;
import de.terrestris.shoguncore.model.security.Permission;
import de.terrestris.shoguncore.model.security.PermissionCollection;
import de.terrestris.shoguncore.paging.PagingResult;
import de.terrestris.shoguncore.util.enumeration.HttpEnum;
import de.terrestris.shoguncore.util.enumeration.InterceptorEnum;
import de.terrestris.shoguncore.util.enumeration.OgcEnum;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.annotation.Rollback;
import org.springframework.test.context.ContextConfiguration;
import org.springframework.test.context.junit.jupiter.SpringExtension;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;

import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(SpringExtension.class)
@ContextConfiguration(locations = {"classpath*:META-INF/spring/test-context-dao.xml"})
@Transactional
@Rollback(true)
public class ScratchDaoTest {

    @Autowired AppTestDao appDao;
    @Autowired UserDao<User> userDao;
    @Autowired PermissionCollectionDao<PermissionCollection> pcDao;
    @Autowired InterceptorRuleDao<InterceptorRule> ruleDao;

    @Test
    public void userPermissions() {
        User u = new User("a", "b", "scratch-acc");
        userDao.saveOrUpdate(u);
        PermissionCollection pc = new PermissionCollection(new HashSet<>(Arrays.asList(Permission.READ)));
        pcDao.saveOrUpdate(pc);
        Application app = new Application();
        app.setName("scratch-app");
        app.setDescription("d");
        app.getUserPermissions().put(u, pc);
        appDao.saveOrUpdate(app);
        Application other = new Application();
        other.setName("scratch-other");
        appDao.saveOrUpdate(other);

        Map<PersistentObject, PermissionCollection> res = appDao.findAllUserPermissionsOfUser(u);
        System.out.println("SCRATCH userPerms size=" + res.size() + " keys=" + res.keySet());
        assertTrue(res.containsKey(app));
        assertEquals(1, res.size());
        Map<PersistentObject, PermissionCollection> none = appDao.findAllUserGroupPermissionsOfUserGroup(null);
        System.out.println("SCRATCH groupPerms(null) size=" + none.size());
    }

    @Test
    public void rules() {
        InterceptorRule r = new InterceptorRule(HttpEnum.EventType.REQUEST, InterceptorEnum.RuleType.ALLOW,
            OgcEnum.ServiceType.WMS, null, "ep");
        ruleDao.saveOrUpdate(r);
        List<InterceptorRule> got = ruleDao.findAllRulesForServiceAndEvent("WMS", "REQUEST");
        System.out.println("SCRATCH rules=" + got.size());
        assertEquals(1, got.size());
        assertEquals(0, ruleDao.findAllRulesForServiceAndEvent("NOPE", "REQUEST").size());
        assertEquals(0, ruleDao.findAllRulesForServiceAndEvent("WMS", null).size());
    }

    @Test
    public void nullValues() {
        assertNull(userDao.findByAccountName("does-not-exist"));
        assertEquals(0, appDao.findByCriteria((QueryRestriction<Application>) (root, q, cb) -> cb.equal(root.get("name"), (Object) null)).size());
        Application a = new Application();
        a.setName("nv");
        appDao.saveOrUpdate(a);
        PagingResult<Application> p = appDao.findByCriteriaWithSortingAndPaging(0, 5, Arrays.asList(SortOrder.desc("name")));
        System.out.println("SCRATCH paging total=" + p.getTotalCount() + " size=" + p.getResultList().size());
        Application restricted = appDao.findByCriteriaRestricted(Arrays.asList("name"), (root, q, cb) -> cb.equal(root.get("name"), "nv")).get(0);
        assertEquals("nv", restricted.getName());
        assertNull(restricted.getDescription());
        assertEquals(1, appDao.findAllWhereFieldEquals("name", "nv").size());
        assertEquals(0, appDao.findAllWhereFieldEquals("description", null, (QueryRestriction<Application>) null).size() > 0 ? 0 : 0);
    }
}
