package de.terrestris.shoguncore.dao;

import de.terrestris.shoguncore.model.Application;
import de.terrestris.shoguncore.model.PersistentObject;
import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.interceptor.InterceptorRule;
import de.terrestris.shoguncore.model.security.Permission;
import de.terrestris.shoguncore.model.security.PermissionCollection;
import de.terrestris.shoguncore.paging.PagingResult;
import de.terrestris.shoguncore.util.enumeration.HttpEnum;
import de.terrestris.shoguncore.util.enumeration.InterceptorEnum;
import de.terrestris.shoguncore.util.enumeration.OgcEnum;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.annotation.Rollback;
import org.springframework.test.context.ContextConfiguration;
import org.springframework.test.context.junit.jupiter.SpringExtension;
import org.springframework.transaction.annotation.Transactional;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests the DAO queries that are built with {@link QueryRestriction}s and
 * {@link SortOrder}s, including the queries that are not covered by
 * {@link GenericHibernateDaoTest}.
 */
@ExtendWith(SpringExtension.class)
@ContextConfiguration(locations = {"classpath*:META-INF/spring/test-context-dao.xml"})
@Transactional
@Rollback(true)
public class QueryRestrictionDaoTest {

    @Autowired
    private AppTestDao appDao;

    @Autowired
    private UserDao<User> userDao;

    @Autowired
    private PermissionCollectionDao<PermissionCollection> permissionCollectionDao;

    @Autowired
    private InterceptorRuleDao<InterceptorRule> interceptorRuleDao;

    @Test
    public void findAllUserPermissionsOfUser_returnsEntitiesWithPermissionsOfTheUser() {
        User user = new User("first", "last", "query-test-account");
        userDao.saveOrUpdate(user);

        PermissionCollection permissions = new PermissionCollection(new HashSet<>(Arrays.asList(Permission.READ)));
        permissionCollectionDao.saveOrUpdate(permissions);

        Application withPermission = new Application();
        withPermission.setName("app with permission");
        withPermission.getUserPermissions().put(user, permissions);
        appDao.saveOrUpdate(withPermission);

        Application withoutPermission = new Application();
        withoutPermission.setName("app without permission");
        appDao.saveOrUpdate(withoutPermission);

        Map<PersistentObject, PermissionCollection> found = appDao.findAllUserPermissionsOfUser(user);

        assertEquals(1, found.size());
        assertTrue(found.containsKey(withPermission));
        assertEquals(permissions, found.get(withPermission));
    }

    @Test
    public void findAllRulesForServiceAndEvent_matchesServiceAndEventOnly() {
        InterceptorRule rule = new InterceptorRule(HttpEnum.EventType.REQUEST, InterceptorEnum.RuleType.ALLOW,
            OgcEnum.ServiceType.WMS, null, "endpoint");
        interceptorRuleDao.saveOrUpdate(rule);

        List<InterceptorRule> found = interceptorRuleDao.findAllRulesForServiceAndEvent("WMS", "REQUEST");
        assertEquals(1, found.size());

        assertEquals(0, interceptorRuleDao.findAllRulesForServiceAndEvent("WFS", "REQUEST").size());
        assertEquals(0, interceptorRuleDao.findAllRulesForServiceAndEvent("WMS", "RESPONSE").size());
        assertEquals(0, interceptorRuleDao.findAllRulesForServiceAndEvent("UNKNOWN", "REQUEST").size());
        assertEquals(0, interceptorRuleDao.findAllRulesForServiceAndEvent("WMS", null).size());
    }

    @Test
    public void findByCriteriaWithSortingAndPaging_sortsDescendingByProperty() {
        Application first = new Application();
        first.setName("sort-a");
        appDao.saveOrUpdate(first);
        Application second = new Application();
        second.setName("sort-b");
        appDao.saveOrUpdate(second);

        PagingResult<Application> result = appDao.findByCriteriaWithSortingAndPaging(
            0, 10, Arrays.asList(SortOrder.desc("name")),
            (root, query, cb) -> cb.like(root.get("name"), "sort-%"));

        assertEquals(Long.valueOf(2), result.getTotalCount());
        assertEquals(Arrays.asList(second, first), result.getResultList());
    }

    @Test
    public void findByUniqueCriteria_returnsNullIfNothingMatches() {
        assertNull(userDao.findByAccountName("this-account-does-not-exist"));
        assertNull(userDao.findByEmail("this-email-does-not-exist@example.com"));
    }

    @Test
    public void findByCriteriaRestricted_returnsOnlyTheRequestedFields() {
        Application app = new Application();
        app.setName("restricted");
        app.setDescription("some description");
        appDao.saveOrUpdate(app);

        List<Application> restricted = appDao.findByCriteriaRestricted(
            Arrays.asList("name"), (root, query, cb) -> cb.equal(root.get("name"), "restricted"));

        assertEquals(1, restricted.size());
        assertEquals("restricted", restricted.get(0).getName());
        assertNull(restricted.get(0).getDescription());
    }

    @Test
    public void findAllWhereFieldEquals_matchesNullValues() {
        Application app = new Application();
        app.setName("null-description");
        appDao.saveOrUpdate(app);

        List<Application> withoutDescription = appDao.findAllWhereFieldEquals("description", null);
        assertTrue(withoutDescription.contains(app));

        app.setDescription("set");
        appDao.saveOrUpdate(app);
        assertFalse(appDao.findAllWhereFieldEquals("description", null).contains(app));
    }

    @Test
    public void sortOrder_exposesPropertyAndDirection() {
        assertEquals("name", SortOrder.asc("name").getProperty());
        assertTrue(SortOrder.asc("name").isAscending());
        assertEquals("id", SortOrder.desc("id").getProperty());
        assertFalse(SortOrder.desc("id").isAscending());
    }
}
